func Transfer(ctx workflow.Context, transfer TransferInput) error {
    ctx = workflow.WithActivityOptions(ctx, workflow.ActivityOptions{
        StartToCloseTimeout: 5 * time.Second,
    })
    // transfer carries the idempotency key used by the Activities.
    if err := workflow.ExecuteActivity(ctx, "Withdraw", transfer).Get(ctx, nil); err != nil {
        return err
    }
    if err := workflow.ExecuteActivity(ctx, "Deposit", transfer).Get(ctx, nil); err != nil {
        // This is a terminal failure, after Activity retries.
        if undoErr := workflow.ExecuteActivity(ctx, "UndoWithdraw", transfer).Get(ctx, nil); undoErr != nil {
            return undoErr
        }
        return err
    }
    return nil
}

