pub async fn run(ctx: &mut WorkflowContext<Self>, input: Input) -> WorkflowResult<Output> {
    let options = ActivityOptions::start_to_close_timeout(Duration::from_secs(30));
    // Movement carries the idempotency key for external side effects.
    ctx.execute_activity(Activities::withdraw, input.clone(), options.clone()).await?;
    if let Err(failure) = ctx.execute_activity(
        Activities::deposit, input.clone(), options.clone(),
    ).await {
        // Terminal deposit failure compensates the earlier withdrawal.
        ctx.execute_activity(Activities::undo_withdraw, input.amount, options).await?;
        return Err(failure.into());
    }
    Ok(Output::completed())
}

