func RepairBranch(ctx workflow.Context, branch Branch) error {
    ctx = workflow.WithActivityOptions(ctx, workflow.ActivityOptions{
        StartToCloseTimeout: 3 * time.Minute,
    })
    for round := 0; round <= maxFixRounds; round++ {
        var tests TestResult
        if err := workflow.ExecuteActivity(ctx, "RunBranchTests", branch).Get(ctx, &tests); err != nil {
            return err
        }
        if tests.Passed { return nil }
        if round == maxFixRounds { break }
        // Python's durable agent turn is represented as an Activity boundary.
        if err := workflow.ExecuteActivity(ctx, "CodeWithFeedback", Feedback{branch, tests.Output}).Get(ctx, nil); err != nil {
            return err
        }
    }
    return temporal.NewNonRetryableApplicationError("Repair limit reached", "TestsFailed", nil)
}

