pub async fn run(ctx: &mut WorkflowContext<Self>, input: Input) -> WorkflowResult<Output> {
    let options = ActivityOptions::start_to_close_timeout(Duration::from_secs(30));
    let mut reply = ctx.execute_activity(Activities::code_subtask, input.clone(), options.clone()).await?;
    for attempt in 0..=3 {
        let tests = ctx.execute_activity(
            Activities::run_branch_tests, input.workspace.clone(), options.clone(),
        ).await?;
        if tests.passed { return Ok(reply); }
        if attempt == 3 { return Err(repair_limit_failure()); }
        // Observed test output becomes feedback for the next agent attempt.
        reply = ctx.execute_activity(
            Activities::repair_subtask, (input.clone(), tests.output), options.clone(),
        ).await?;
    }
    unreachable!()
}

